import 'package:flutter_test/flutter_test.dart'; import 'package:project_zion/core/magiczionos/magiczionos.dart';
void main(){test('default policy never enables dangerous commands',(){const c=MagiczionosConfig();expect(c.allowDangerousCommands,false);expect(c.preferredStrategy,RootStrategy.auto);});test('strategies expose distinct priorities',(){expect(MagiczionosStrategy().priority,100);expect(ChrootStrategy().priority,75);expect(ProotStrategy().priority,50);});test('status enum is explicit',(){expect(StrategyStatus.values.map((e)=>e.name),containsAll(['available','permissionRequired','notConfigured','unavailable']));});}